library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity bbq_watchdog_core is generic(COUNT_WIDTH:positive:=24;TIMEOUT_TICKS:positive:=1000);port(clk,rst_n,enable,kick,clear_fault:in std_logic;timeout_pulse,fault_latched:out std_logic;count:out std_logic_vector(COUNT_WIDTH-1 downto 0));end;
architecture rtl of bbq_watchdog_core is signal c:unsigned(COUNT_WIDTH-1 downto 0):=(others=>'0');signal f,t:std_logic:='0';begin count<=std_logic_vector(c);fault_latched<=f;timeout_pulse<=t;process(clk)begin if rising_edge(clk)then t<='0';if rst_n='0'then c<=(others=>'0');f<='0';elsif clear_fault='1'then f<='0';c<=(others=>'0');elsif enable='0' or kick='1'then c<=(others=>'0');elsif c>=to_unsigned(TIMEOUT_TICKS-1,COUNT_WIDTH)then c<=(others=>'0');f<='1';t<='1';else c<=c+1;end if;end if;end process;end architecture;
